import {form,number as num,select as sel,text,area,result,outputText,e,n,download} from '../ui.mjs';
import {dateOffset} from '../advanced-core.mjs';
import {bsMonths,holidays} from './nepal-data.mjs';
import {bsToAD,adToBS,nepaliNumberWords,nebGrades,devanagari} from './nepal-core.mjs';
import {need,table,today,exportCSV} from './shared.mjs';
import {icsEscape} from './calc-core.mjs';
const monthNames=['Baisakh','Jestha','Asar','Shrawan','Bhadra','Aswin','Kartik','Mangsir','Poush','Magh','Falgun','Chaitra'];
export function setupNepal(tool,mount,out){const id=tool.id,show=o=>result(out,o);const forms={
 'bs-ad-converter':()=>form(mount,[sel('direction','Convert',[['bs','BS → AD'],['ad','AD → BS']],'bs'),text('bs','Bikram Sambat date (YYYY-MM-DD)','2083-01-01'),text('ad','Gregorian date','2026-04-14','date')],v=>{const value=v.direction==='bs'?bsToAD(v.bs):adToBS(v.ad);show({label:v.direction==='bs'?'Gregorian date':'Bikram Sambat date',value,details:[['Nepali digits',devanagari(value)],['Table range','BS 2000–2090 / AD 1943-04-14–2034-04-13']],copy:value,note:'Uses month-by-month calendar data, not a fixed year offset. Only the chosen input direction is used.'});},{label:'Convert calendar date'}),
 'unicode-preeti':()=>form(mount,[sel('direction','Direction',[['preeti','Unicode → Preeti'],['unicode','Preeti → Unicode']],'preeti'),area('input','Text','नेपाल निर्माण विद्यार्थी'),sel('preserve','Mixed text handling',[['all','Convert all entered text'],['mixed','Preserve likely English text when decoding']],'all')],async v=>{const {preetiToUnicode,unicodeToPreeti}=await import('../assets/vendor/preeti.mjs');let value;if(v.direction==='preeti')value=unicodeToPreeti(v.input);else if(v.preserve==='mixed'){const {convertMixed}=await import('../assets/vendor/preeti.mjs');value=convertMixed(v.input);}else value=preetiToUnicode(v.input);outputText(out,value,[['Output',v.direction==='preeti'?'Legacy Preeti encoding — use Preeti font in target document':'Unicode Nepali text']]);},{label:'Convert Nepali text',note:'Proofread conjuncts and mixed English. A Preeti font is needed in the destination document to display legacy output as Nepali.'}),
 'neb-grade':()=>form(mount,[area('subjects','Subject | theory marks | theory max | theory credits | internal marks | internal max | internal credits','English | 57 | 75 | 3 | 18 | 25 | 1\nComputer | 45 | 50 | 2 | 46 | 50 | 2')],v=>{const r=nebGrades(v.subjects);show({label:'Estimated credit-weighted GPA',value:r.gpa===null?'Minimum component rule not met':r.gpa.toFixed(3),details:[['Entered component credits',n(r.credits)],['Theory minimum','35% (D)'],['Internal minimum','40% (C)'],['Scheme','2078 directive, fourth amendment 2081/03/16']],html:table(['Subject','Component','Percent','Grade','Point','Credits','Minimum'],r.components.map(c=>[c.subject,c.component,n(c.percent)+'%',c.grade,c.point===null?'—':c.point,c.credits,c.meetsMinimum?'Met':'Not met'])),copy:JSON.stringify(r,null,2),note:'Components are graded separately. An NG or failed minimum is not averaged as zero. Enter actual component credits; this is not an official transcript.'});exportCSV(out,r.components,'nepocore-neb-components.csv');},{label:'Estimate component grades & GPA',note:'Example credit values are illustrative. Replace them with the actual credits on your grade sheet. Theory/internal percentages are calculated separately.'}),
 'nepali-words':()=>form(mount,[text('amount','Number or amount','125000.50','text',true),sel('mode','Output',[['rupee','Rupees and paisa'],['number','General number words']],'rupee')],v=>{const value=nepaliNumberWords(v.amount,v.mode==='rupee');outputText(out,value,[['Nepali digits',devanagari(v.amount)]]);},{label:'Write in Nepali words'}),
 'nepali-holidays':()=>holidaysTool(mount,out)
 };need(forms[id],'This Nepal tool is unavailable.');forms[id]();}
function holidaysTool(mount,out){let current=1;try{const bs=adToBS(today());if(bs.startsWith('2083'))current=+bs.split('-')[1];}catch{}const f=form(mount,[sel('month','BS 2083 month',[[0,'All months'],...monthNames.map((x,i)=>[i+1,x])],current),sel('scope','Holiday scope',[['all','All scopes — read restrictions'],['national','National entries only']],'all')],v=>{const month=+v.month,list=holidays.filter(h=>(v.scope==='all'||h.scope==='national')&&(!month||h.dateAD&&Array.from({length:h.days||1},(_,i)=>+adToBS(dateOffset(h.dateAD,i)).slice(5,7)).includes(month)));let calendar='';if(month){const firstAD=bsToAD(`2083-${String(month).padStart(2,'0')}-01`),start=new Date(firstAD+'T00:00:00Z').getUTCDay(),count=bsMonths[2083][month-1];calendar='<div class="nepali-calendar"><h3>'+monthNames[month-1]+' २०८३</h3><div class="calendar-week">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="calendar-days">'+'<span></span>'.repeat(start);for(let d=1;d<=count;d++){const ad=dateOffset(firstAD,d-1),events=list.filter(h=>h.dateAD&&ad>=h.dateAD&&ad<dateOffset(h.dateAD,h.days||1));calendar+=`<div class="calendar-day ${events.length?'has-event':''}" title="${e(events.map(h=>h.name.en+' · '+h.scope).join('; '))}"><strong>${devanagari(d)}</strong><small>${ad.slice(5)}</small>${events.length?'<span class="event-dot"></span>':''}</div>`;}calendar+='</div></div>';}showResults();function showResults(){result(out,{label:'Sourced holiday entries',value:list.length,html:calendar+table(['Holiday','BS date','AD date','Days','Scope / type'],list.map(h=>[h.name.ne+' · '+h.name.en,h.dateBS||'Date not fixed',h.dateAD||'Undated',h.days||1,h.scope+' · '+h.kind])),copy:list.map(h=>(h.dateBS||'Undated')+' '+h.name.en+' ('+h.scope+')').join('\n'),note:'Bundled BS 2083 government notice. Scope restrictions matter; observances and offices-open entries are not blanket national closures. Undated lunar entries are shown only in All months.'});exportCSV(out,list.map(h=>({name:h.name.en,name_ne:h.name.ne,date_bs:h.dateBS||'',date_ad:h.dateAD||'',days:h.days||1,scope:h.scope,kind:h.kind})),'nepocore-holidays-2083.csv');const b=document.createElement('button');b.className='btn secondary small';b.textContent='Download dated events (ICS)';b.onclick=()=>{const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Nepocore//Nepal holidays 2083//EN'];for(const h of list.filter(x=>x.dateAD)){lines.push('BEGIN:VEVENT','UID:'+h.id+'-2083@nepocore','DTSTAMP:20261028T000000Z','DTSTART;VALUE=DATE:'+h.dateAD.replaceAll('-',''),'DTEND;VALUE=DATE:'+dateOffset(h.dateAD,h.days||1).replaceAll('-',''),'SUMMARY:'+icsEscape(h.name.en+' ['+h.scope+']'),'DESCRIPTION:'+icsEscape(h.kind+'; '+h.name.ne+'; see official notice for scope.'),'END:VEVENT');}lines.push('END:VCALENDAR','');download(new Blob([lines.join('\r\n')],{type:'text/calendar'}),'nepocore-holidays-2083.ics');};out.querySelector('.result-actions').append(b);}},{label:'View holiday calendar',note:'Year coverage: BS 2083 (2026-04-14 to 2027-04-13). Source: Nepal Ministry of Home Affairs notice. Special announcements after the bundled notice are not automatically fetched.'});f.addEventListener('change',()=>f.requestSubmit());}
